//! Checks src/runtime/ops.zig against tables generated by node (tests/harness/golden.js).
//! Numbers are compared bit for bit (via their IEEE-754 encoding), so -0 vs 0 and every
//! last digit matter. Any NaN matches any NaN.

const std = @import("std");
const testing = std.testing;
const ops = @import("zqjs").ops;

fn fromBits(hex: []const u8) !f64 {
    return @bitCast(try std.fmt.parseInt(u64, hex, 16));
}

fn sameNumber(a: f64, b: f64) bool {
    if (std.math.isNan(a) and std.math.isNan(b)) return true;
    return @as(u64, @bitCast(a)) == @as(u64, @bitCast(b));
}

fn lines(comptime file: []const u8) std.mem.SplitIterator(u8, .scalar) {
    return std.mem.splitScalar(u8, @embedFile(file), '\n');
}

test "Number::toString matches node" {
    var failures: usize = 0;
    var it = lines("ops/number_to_string.jsonl");
    while (it.next()) |line| {
        if (line.len == 0) continue;
        const parsed = try std.json.parseFromSlice([2][]const u8, testing.allocator, line, .{});
        defer parsed.deinit();
        const x = try fromBits(parsed.value[0]);
        var buf: ops.NumberBuf = undefined;
        const got = ops.formatNumber(&buf, x);
        if (!std.mem.eql(u8, got, parsed.value[1])) {
            if (failures < 20) std.debug.print("String({s}): expected {s}, got {s}\n", .{ parsed.value[0], parsed.value[1], got });
            failures += 1;
        }
    }
    try testing.expectEqual(@as(usize, 0), failures);
}

test "StringToNumber matches node" {
    var failures: usize = 0;
    var it = lines("ops/string_to_number.jsonl");
    while (it.next()) |line| {
        if (line.len == 0) continue;
        const parsed = try std.json.parseFromSlice([2][]const u8, testing.allocator, line, .{});
        defer parsed.deinit();
        const units = try std.unicode.utf8ToUtf16LeAlloc(testing.allocator, parsed.value[0]);
        defer testing.allocator.free(units);
        const expected = try fromBits(parsed.value[1]);
        const got = try ops.stringToNumber(testing.allocator, units);
        if (!sameNumber(got, expected)) {
            if (failures < 20) std.debug.print("+{s}: expected {d}, got {d}\n", .{ line[0..@min(line.len, 60)], expected, got });
            failures += 1;
        }
    }
    try testing.expectEqual(@as(usize, 0), failures);
}

test "arithmetic operators match node, including -0, NaN and Infinity" {
    var failures: usize = 0;
    var pow_inexact: usize = 0;
    var it = lines("ops/arithmetic.jsonl");
    while (it.next()) |line| {
        if (line.len == 0) continue;
        const parsed = try std.json.parseFromSlice([4][]const u8, testing.allocator, line, .{});
        defer parsed.deinit();
        const op = parsed.value[0];
        const a = try fromBits(parsed.value[1]);
        const b = try fromBits(parsed.value[2]);
        const expected = try fromBits(parsed.value[3]);
        const got: f64 = if (std.mem.eql(u8, op, "+")) a + b //
        else if (std.mem.eql(u8, op, "-")) a - b //
        else if (std.mem.eql(u8, op, "*")) a * b //
        else if (std.mem.eql(u8, op, "/")) a / b //
        else if (std.mem.eql(u8, op, "%")) ops.remainder(a, b) //
            else ops.pow(a, b);
        if (!sameNumber(got, expected)) {
            // Known deviation (DESIGN_DECISIONS D25): std.math.pow is less accurate than
            // V8's pow. Exact and special cases must still match; the inexact ones are
            // capped at today's count so any regression fails the test.
            if (std.mem.eql(u8, op, "**") and !isExactCase(a, b, expected)) {
                pow_inexact += 1;
                continue;
            }
            if (failures < 20) std.debug.print("{d} {s} {d}: expected {d}, got {d}\n", .{ a, op, b, expected, got });
            failures += 1;
        }
    }
    try testing.expectEqual(@as(usize, 0), failures);
    try testing.expect(pow_inexact <= 8);
}

/// Results that any correct pow must produce exactly: special values, and integral
/// results representable exactly.
fn isExactCase(a: f64, b: f64, expected: f64) bool {
    if (std.math.isNan(a) or std.math.isNan(b) or std.math.isInf(a) or std.math.isInf(b)) return true;
    if (a == 0 or b == 0 or expected == 0 or std.math.isInf(expected)) return true;
    return @abs(expected) < 0x1p53 and @floor(expected) == expected;
}
